					<text class="city-arrow">▼</text>
					<text class="weather-text" v-if="weatherText">{{ weatherText }}</text>
				</view>
				<button class="locate-action" @click="locateCurrentPosition">重新定位</button>
			</view>

			<view class="pickup-bubble" @click="choosePickupAddress">
				<text class="bubble-title">{{ pickupEtaText }}</text>
				<text class="bubble-sub">{{ nearbyRiderText }}</text>
			</view>

			<view class="map-notice">
				<text>选择取货地址后，系统会查询附近可接单骑手</text>
			</view>
		</view>

		<scroll-view class="home-content" scroll-y>
			<view class="intro-card">
				<text class="intro-title">即时跑腿配送</text>
				<text class="intro-desc">填写取货和收货地址，查看附近骑手并发起订单</text>
			</view>

			<view class="order-card">
				<view class="service-tabs">
					<view
						v-for="item in serviceTabs"
						:key="item.value"
						:class="['service-tab', selectedService === item.value ? 'active' : '']"
						@click="selectedService = item.value"
					>
						{{ item.label }}
					</view>
				</view>

				<view class="address-card">
					<view class="address-row" @click="choosePickupAddress">
						<view class="address-badge pickup">发</view>
						<view class="address-main">
							<text class="address-title">{{ pickupTitle }}</text>
							<text class="address-sub">{{ pickupSubTitle }}</text>
						</view>
					</view>
					<view class="address-row" @click="chooseDropAddress">
						<view class="address-badge drop">收</view>
						<view class="address-main">
							<text class="address-title">{{ dropTitle }}</text>
							<text class="address-sub">{{ dropSubTitle }}</text>
						</view>
					</view>
				</view>

				<view :class="['rider-strip', nearbyRiderCount === 0 ? 'warning' : '']">
					<text>{{ nearbyRiderText }}</text>
					<text>{{ pickupEtaText }}</text>
				</view>

				<button class="primary-btn" @click="goNextOrder">下一步：完善订单</button>
			</view>

			<view class="process-card">
				<text class="process-title">下单流程</text>
				<view class="process-steps">
					<view class="process-step">
						<view class="step-icon">写</view>
						<text>填写地址</text>
					</view>
					<view class="process-step">
						<view class="step-icon">付</view>
						<text>确认支付</text>
					</view>
					<view class="process-step">
						<view class="step-icon">送</view>
						<text>骑手配送</text>
					</view>
				</view>
			</view>
		</scroll-view>

		<nut-toast></nut-toast>
		<nut-notify></nut-notify>
	</view>
</template>

<script>
	import { getWeatherByAdcode } from "@/request/apis/amap.js"
	import { getNearbyRiderCount } from "@/request/apis/order.js"
	import { toRaw } from "vue";

	const DEFAULT_CITY = {
		name: '\u54c8\u5c14\u6ee8\u5e02',
		cityName: '\u54c8\u5c14\u6ee8\u5e02',
		cityCode: '230100',
		adcode: '230100',
		centerLng: 126.642464,
		centerLat: 45.756967
	}

	export default {
		data() {
			return {
				weather: {
					weather: '',
					temperature: ''
				},
				currSchool: null,
				currentCity: DEFAULT_CITY,
				mapCenter: {
					lng: DEFAULT_CITY.centerLng,
					lat: DEFAULT_CITY.centerLat
				},
				currentLocation: null,
				pickupAddress: null,
				dropAddress: null,
				nearbyRiderCount: null,
				nearbyRiderLoading: false,
				selectedService: 'qusong',
				serviceTabs: [
					{ label: '\u5e2e\u53d6\u9001', value: 'qusong' },
					{ label: '\u5e2e\u4e70', value: 'bangmai' },
					{ label: '\u4e07\u80fd\u8dd1\u817f', value: 'wanneng' }
				]
			}
		},
		computed: {
			currentCityName() {
				return this.currentCity.cityName || this.currentCity.name || '\u9009\u62e9\u57ce\u5e02'
			},
			weatherText() {
				if (!this.weather || !this.weather.temperature) {
					return ''
				}
				return `${this.weather.weather || ''} ${this.weather.temperature}\u00b0`
			},
			pickupTitle() {
				return this.pickupAddress && this.pickupAddress.title ? this.pickupAddress.title : '\u8bf7\u9009\u62e9\u53d6\u8d27\u5730\u5740'
			},
			pickupSubTitle() {
				return this.pickupAddress && this.pickupAddress.detail ? this.pickupAddress.detail : '\u9009\u62e9\u540e\u53ef\u67e5\u770b\u9644\u8fd1\u9a91\u624b\u6570\u91cf'
			},
			dropTitle() {
				return this.dropAddress && this.dropAddress.title ? this.dropAddress.title : '\u9001\u5230\u54ea\u91cc'
			},
			dropSubTitle() {
				return this.dropAddress && this.dropAddress.detail ? this.dropAddress.detail : '\u8bf7\u9009\u62e9\u6536\u8d27\u5730\u5740'
			},
			nearbyRiderText() {
				if (this.nearbyRiderLoading) {
					return '\u6b63\u5728\u67e5\u8be2\u9644\u8fd1\u9a91\u624b'
				}
				if (!this.pickupAddress) {
					return '\u9009\u62e9\u53d6\u8d27\u5730\u5740\u540e\u67e5\u770b\u9644\u8fd1\u9a91\u624b'
				}
				if (this.nearbyRiderCount === null) {
					return '\u9644\u8fd1\u9a91\u624b\u6570\u91cf\u6682\u672a\u83b7\u53d6'
				}
				if (this.nearbyRiderCount === 0) {
					return '\u9644\u8fd1\u9a91\u624b\u8f83\u5c11\uff0c\u63a5\u5355\u53ef\u80fd\u53d8\u6162'
				}
				return `\u9644\u8fd1\u7ea6${this.nearbyRiderCount}\u540d\u9a91\u624b\u53ef\u63a5\u5355`
			},
			pickupEtaText() {
				if (!this.pickupAddress) {
					return '\u70b9\u51fb\u9009\u62e9\u53d6\u8d27\u5730\u5740'
				}
				if (this.nearbyRiderCount === 0) {
					return '\u63a5\u5355\u53ef\u80fd\u8f83\u6162'
				}
				if (this.nearbyRiderCount === null) {
					return '\u7b49\u5f85\u8fd0\u529b\u67e5\u8be2'
				}
				return '\u9884\u8ba1\u8f83\u5feb\u54cd\u5e94'
			},
			mapMarkers() {
				const markers = []
				if (this.pickupAddress && this.pickupAddress.lat && (this.pickupAddress.lng || this.pickupAddress.lon)) {
					markers.push({
						id: 1,
						latitude: Number(this.pickupAddress.lat),
						longitude: Number(this.pickupAddress.lng || this.pickupAddress.lon),
						title: this.pickupAddress.title || '\u53d6\u8d27\u5730\u5740',
						iconPath: '/static/icons/start.png',
						width: 32,
						height: 32
					})
				}
				if (this.dropAddress && this.dropAddress.lat && (this.dropAddress.lng || this.dropAddress.lon)) {
					markers.push({
						id: 2,
						latitude: Number(this.dropAddress.lat),
						longitude: Number(this.dropAddress.lng || this.dropAddress.lon),
						title: this.dropAddress.title || '\u6536\u8d27\u5730\u5740',
						iconPath: '/static/icons/end.png',
						width: 32,
						height: 32
					})
				}
				return markers
			}
		},
		watch: {
			"$store.state.appLaunch": function(val) {
				if (val) {
					this.initHome()
				}
			}
		},
		mounted() {
			this.initHome()
		},
		onLoad() {
			const timer = setInterval(() => {
				if (this.$store.state.appLaunch) {
					this.initHome()
					clearInterval(timer)
				}
			}, 100)
		},
		onShow() {
			this.loadCityByStore()
		},
		methods: {
			initHome() {
				this.loadCityByStore()
				this.initWeather()
				if (!this.currentLocation) {
					this.locateCurrentPosition(true)
				}
			},
			loadCityByStore() {
				const city = toRaw(this.$store.state.currentCity || uni.getStorageSync("currentCity") || DEFAULT_CITY)
				this.currentCity = {
					...DEFAULT_CITY,
					...city,
					name: city.name || city.cityName || DEFAULT_CITY.name,
					cityName: city.cityName || city.name || DEFAULT_CITY.cityName
				}
				this.currSchool = toRaw(this.$store.state.currSchool || uni.getStorageSync("currentSchool") || null)
				if (!this.currentLocation && this.currentCity.centerLng && this.currentCity.centerLat) {
					this.mapCenter = {
						lng: Number(this.currentCity.centerLng),
						lat: Number(this.currentCity.centerLat)
					}
				}
			},
			initWeather() {
				const cached = this.$store.state.weather || null
				if (cached) {
					this.weather = cached
					return
				}
				if (!this.currentCity || !this.currentCity.adcode) {
					return
				}
				getWeatherByAdcode(this.currentCity.adcode).then(res => {
					this.weather = res.data || {}
					this.$store.commit('setWeather', this.weather)
				}).catch(() => {})
			},
			locateCurrentPosition(silent = false) {
				uni.getLocation({
					type: 'gcj02',
					success: (res) => {
						this.currentLocation = {
							lng: res.longitude,
							lat: res.latitude
						}
						this.mapCenter = {
							lng: res.longitude,
							lat: res.latitude
						}
						this.$store.commit('setCurrentLocation', this.currentLocation)
					},
					fail: () => {
						if (!silent) {
							uni.showToast({
								title: '\u5b9a\u4f4d\u5931\u8d25\uff0c\u8bf7\u68c0\u67e5\u4f4d\u7f6e\u6743\u9650',
								icon: 'none'
							})
						}
					}
				})
			},
			choosePickupAddress() {
				this.chooseMapAddress('pickup')
			},
			chooseDropAddress() {
				this.chooseMapAddress('drop')
			},
			chooseMapAddress(type) {
				uni.chooseLocation({
					latitude: this.mapCenter.lat,
					longitude: this.mapCenter.lng,
					success: (res) => {
						const address = this.buildOrderAddress(res)
						if (type === 'pickup') {
							this.pickupAddress = address
							this.mapCenter = {
								lng: Number(address.lng),
								lat: Number(address.lat)
							}
							this.refreshNearbyRiderCount()
						} else {
							this.dropAddress = address
						}
					},
					fail: () => {
						uni.showToast({
							title: '\u672a\u9009\u62e9\u5730\u5740',
							icon: 'none'
						})
					}
				})
			},
			buildOrderAddress(location) {
				return {
					id: '',
					name: '',
					phone: '',
					title: location.name || '\u5730\u56fe\u9009\u70b9',
					detail: location.address || '',
					lat: location.latitude,
					lon: location.longitude,
					lng: location.longitude
				}
			},
			refreshNearbyRiderCount() {
				if (!this.pickupAddress || !this.pickupAddress.lat || !(this.pickupAddress.lng || this.pickupAddress.lon)) {
					this.nearbyRiderCount = null
					return
				}
				this.nearbyRiderLoading = true
				getNearbyRiderCount({
					lng: this.pickupAddress.lng || this.pickupAddress.lon,
					lat: this.pickupAddress.lat
				}).then(res => {
					const data = res.data || {}
					this.nearbyRiderCount = Number(data.nearbyRiderCount || 0)
				}).catch(() => {
					this.nearbyRiderCount = null
				}).finally(() => {
					this.nearbyRiderLoading = false
				})
			},
			goNextOrder() {
				if (!this.pickupAddress) {
					uni.showToast({
						title: '\u8bf7\u5148\u9009\u62e9\u53d6\u8d27\u5730\u5740',
						icon: 'none'
					})
					return
				}
				const routeMap = {
					qusong: '/pages/API/order/qusong/qusong',
					bangmai: '/pages/API/order/bangmai/bangmai',
					wanneng: '/pages/API/order/wanneng/wanneng'
				}
				const params = [
					`startAddress=${encodeURIComponent(JSON.stringify(this.pickupAddress))}`
				]
				if (this.dropAddress) {
					params.push(`endAddress=${encodeURIComponent(JSON.stringify(this.dropAddress))}`)
				}
				uni.navigateTo({
					url: `${routeMap[this.selectedService]}?${params.join('&')}`
				})
			},
			goToSelectSchool() {
				uni.navigateTo({
					url: "/pages/API/school/select/select"
				})
			}
		}
	}
</script>

